// ============ CONFIGURACIÓN DEL CLIENTE (edita solo este bloque) ============
const CONFIG_BASE = {
  tienda: 'Tienda Demo',
  proveedor: 'Proveedor Demo',

  fuente: 'demo',                 // 'demo' o 'url'
  feed_url: '',                   // si fuente = 'url': CSV o XML del proveedor
  destino: 'demo',                // 'demo', 'shopify' o 'woocommerce'
  dominio_shopify: '',            // solo Shopify: tu-tienda.myshopify.com
  location_id: '',                // solo Shopify: almacén sobre el que se ajusta el stock

  modo_prueba: true,              // true = calcula y avisa, pero NO toca la tienda
  avisar_cambio_precio_pct: 3,    // avisa si el proveedor sube o baja un precio más de este %

  // --- frenos de seguridad: si el feed llega mal, mejor no tocar nada ---
  min_referencias: 5,             // por debajo de esto, el feed se considera incompleto
  max_cambios_pct: 40,            // si cambiaría más de este % del catálogo, se bloquea
  max_agotados_pct: 25,           // si dejaría agotado más de este % del catálogo, se bloquea
  margen_stock: 0,                // resta unidades al stock del proveedor (colchón de seguridad)

  email_to: 'cliente@ejemplo.com',
  email_from: 'stock@tu-dominio.com',
  telegram_chat_id: 'TU_CHAT_ID',
};
// ============================================================================

// ---- Panel único de Denoro: los ajustes del cliente llegan en la entrada ----
const __ENTRADA = $input.first().json || {};
const __limpio = (o) => Object.fromEntries(Object.entries(o || {}).filter(([, x]) => x !== '' && x !== null && x !== undefined));
const __mezclar = (b, o) => {
  const r = { ...b };
  for (const [k, v] of Object.entries(o || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v) && b[k] && typeof b[k] === 'object' && !Array.isArray(b[k])) r[k] = { ...b[k], ...__limpio(v) };
    else if (v !== undefined && v !== null) r[k] = v;
  }
  return r;
};
const CONFIG = { ...__mezclar(CONFIG_BASE, __ENTRADA.config), __token: String(__ENTRADA.token || ''), __auto: String(__ENTRADA.auto || ''), __clave: String(__ENTRADA.clave || '') };
if (!CONFIG.__token || !CONFIG.__clave) throw new Error('Esta versión se lanza desde el panel de Denoro (falta el cliente)');
if (!['demo', 'url'].includes(CONFIG.fuente)) throw new Error(`fuente "${CONFIG.fuente}" no válida: usa demo o url`);
if (!['demo', 'shopify', 'woocommerce'].includes(CONFIG.destino)) {
  throw new Error(`destino "${CONFIG.destino}" no válido: usa demo, shopify o woocommerce`);
}
if (CONFIG.fuente === 'url' && !/^https?:\/\//i.test(String(CONFIG.feed_url || ''))) {
  throw new Error('Con fuente = url hace falta un feed_url que empiece por http:// o https://');
}
if (CONFIG.destino === 'shopify' && !CONFIG.modo_prueba) {
  if (!/\.myshopify\.com$/i.test(String(CONFIG.dominio_shopify || ''))) {
    throw new Error('Con destino = shopify hace falta dominio_shopify (tu-tienda.myshopify.com)');
  }
  if (!String(CONFIG.location_id || '').trim()) {
    throw new Error('Con destino = shopify hace falta location_id: el almacén sobre el que se ajusta el stock');
  }
}
for (const [k, min, max] of [['max_cambios_pct', 1, 100], ['max_agotados_pct', 1, 100],
  ['min_referencias', 1, 1e6], ['avisar_cambio_precio_pct', 0, 100]]) {
  if (!(CONFIG[k] >= min && CONFIG[k] <= max)) throw new Error(`${k} debe estar entre ${min} y ${max}`);
}
if (CONFIG.margen_stock < 0) throw new Error('margen_stock no puede ser negativo');
const PLACEHOLDER = /ejemplo\.com|tu-dominio|TU_CHAT_ID/i;
for (const k of ['email_to', 'email_from', 'telegram_chat_id']) {
  if (PLACEHOLDER.test(String(CONFIG[k] || ''))) {
    throw new Error(`Configura "${k}" en el nodo Configuración (ahora tiene un valor de ejemplo). Déjalo vacío ('') para desactivar ese canal.`);
  }
}
if (CONFIG.telegram_chat_id && !/^-?\d+$|^@\w+$/.test(String(CONFIG.telegram_chat_id))) {
  throw new Error('telegram_chat_id debe ser un número (p. ej. 123456789) o @canal');
}
if (!CONFIG.email_to && !CONFIG.telegram_chat_id) throw new Error('Configura al menos un canal: email_to o telegram_chat_id');
if (CONFIG.email_to && !CONFIG.email_from) throw new Error('Falta email_from (la cuenta SMTP que envía)');

return [{ json: {
  ...CONFIG,
  enviar_email: Boolean(CONFIG.email_to),
  enviar_telegram: Boolean(CONFIG.telegram_chat_id),
  generado_en: new Date().toISOString(),
} }];

// Lee el feed del proveedor. Acepta CSV (con ; o ,) y XML, y detecta cuál es por el contenido.
const cfg = $('Configuración').first().json;
const entrada = $input.first();
let texto = entrada.json.data ?? entrada.json.body ?? '';
if (!texto && entrada.binary) {
  const key = Object.keys(entrada.binary)[0];
  texto = Buffer.from(entrada.binary[key].data, 'base64').toString('utf8');
}
texto = String(texto).replace(/^\uFEFF/, '').trim();
if (!texto) throw new Error('El feed del proveedor llegó vacío: revisa feed_url en el nodo Configuración');

const numero = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim();
  // "1.234,56" -> 1234.56 ; "1,234.56" -> 1234.56 ; "12,5" -> 12.5
  const limpio = /,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  const n = parseFloat(limpio.replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const clave = (s) => String(s).trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/^g:/, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const ALIAS = {
  sku: ['sku', 'referencia', 'ref', 'codigo', 'id', 'mpn', 'ean', 'item_id'],
  stock: ['stock', 'existencias', 'inventario', 'cantidad', 'qty', 'quantity', 'availability', 'disponibilidad'],
  precio: ['precio', 'price', 'pvp', 'sale_price', 'precio_venta'],
  titulo: ['titulo', 'title', 'nombre', 'name', 'descripcion_corta'],
};
const deAlias = (obj) => {
  const out = {};
  for (const [destino, nombres] of Object.entries(ALIAS)) {
    const k = Object.keys(obj).find((h) => nombres.includes(h));
    if (k !== undefined) out[destino] = obj[k];
  }
  return out;
};
// "in stock" / "out of stock" también son formas válidas de decir el stock
const stockDe = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const s = String(v).trim().toLowerCase();
  if (/^(out of stock|agotado|sin stock|no|false|0)$/.test(s)) return 0;
  if (/^(in stock|disponible|si|sí|true)$/.test(s)) return null; // disponible pero sin cantidad
  return numero(s);
};

let filas = [];
if (texto.startsWith('<')) {
  // ---- XML: se buscan los bloques que se repiten (item, product, entry, producto) ----
  const bloques = texto.match(/<(item|product|producto|entry|articulo)\b[\s\S]*?<\/\1>/gi) || [];
  if (!bloques.length) throw new Error('El XML no trae bloques <item>, <product> o <entry>');
  filas = bloques.map((bloque) => {
    // fuera la etiqueta que envuelve el bloque, o se leería el producto entero como un solo campo
    const b = bloque.replace(/^<[a-z0-9:_\-]+(?:\s[^>]*)?>/i, '').replace(/<\/[a-z0-9:_\-]+>\s*$/i, '');
    const campos = {};
    for (const m of b.matchAll(/<([a-z0-9:_\-]+)(?:\s[^>]*)?>([\s\S]*?)<\/\1>/gi)) {
      const valor = m[2].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/<[^>]*>/g, '').trim();
      const k = clave(m[1]);
      if (valor && campos[k] === undefined) campos[k] = valor;
    }
    return campos;
  });
} else {
  // ---- CSV ----
  const primera = texto.split('\n')[0];
  const sep = (primera.match(/;/g) || []).length > (primera.match(/,/g) || []).length ? ';' : ',';
  const celdas = [];
  let campo = ''; let fila = []; let comillas = false;
  for (let i = 0; i < texto.length; i++) {
    const ch = texto[i];
    if (comillas) {
      if (ch === '"' && texto[i + 1] === '"') { campo += '"'; i++; }
      else if (ch === '"') comillas = false;
      else campo += ch;
    } else if (ch === '"') comillas = true;
    else if (ch === sep) { fila.push(campo); campo = ''; }
    else if (ch === '\n') { fila.push(campo); celdas.push(fila); fila = []; campo = ''; }
    else if (ch !== '\r') campo += ch;
  }
  if (campo !== '' || fila.length) { fila.push(campo); celdas.push(fila); }
  if (celdas.length < 2) throw new Error('El CSV del proveedor no tiene filas de datos');
  const cabecera = celdas[0].map(clave);
  filas = celdas.slice(1).map((f) => Object.fromEntries(cabecera.map((h, i) => [h, f[i]])));
}

const salida = [];
const vistos = new Set();
for (const cruda of filas) {
  const c = deAlias(cruda);
  const sku = String(c.sku ?? '').trim();
  if (!sku || vistos.has(sku)) continue;
  vistos.add(sku);
  const stock = stockDe(c.stock);
  salida.push({ json: {
    _lado: 'feed', sku,
    titulo: c.titulo ? String(c.titulo).trim() : '',
    stock: stock === null ? null : Math.max(0, Math.round(stock)),
    precio: numero(c.precio),
    proveedor: cfg.proveedor,
  } });
}
if (!salida.length) {
  throw new Error(`El feed no trajo ninguna referencia reconocible. Columnas vistas: ${Object.keys(filas[0] || {}).join(', ') || '(ninguna)'}`);
}
return salida;

// Foto del catálogo de Shopify: una línea por variante, que es lo que tiene SKU y stock.
const salida = [];
for (const item of $input.all()) {
  const p = item.json;
  for (const v of p.variants || []) {
    if (!v.sku) continue;
    salida.push({ json: {
      _lado: 'tienda',
      sku: String(v.sku).trim(),
      titulo: (p.variants || []).length > 1 ? `${p.title} · ${v.title}` : p.title,
      stock: v.inventory_quantity ?? null,
      precio: v.price != null ? parseFloat(v.price) : null,
      id_tienda: v.id,
      inventory_item_id: v.inventory_item_id,
      gestiona_stock: v.inventory_management === 'shopify',
    } });
  }
}
if (!salida.length) throw new Error('Shopify no devolvió variantes con SKU: sin SKU no se puede casar el feed con la tienda');
return salida;

// Foto del catálogo de WooCommerce.
const salida = [];
for (const item of $input.all()) {
  const p = item.json;
  if (!p.sku) continue;
  salida.push({ json: {
    _lado: 'tienda',
    sku: String(p.sku).trim(),
    titulo: p.name || '',
    stock: p.stock_quantity ?? null,
    precio: p.price != null && p.price !== '' ? parseFloat(p.price) : null,
    id_tienda: p.id,
    gestiona_stock: p.manage_stock !== false,
  } });
}
if (!salida.length) throw new Error('WooCommerce no devolvió productos con SKU: sin SKU no se puede casar el feed con la tienda');
return salida;

const __estadoCliente = () => { const g = $getWorkflowStaticData('global'); const k = String($('Configuración').first().json.__token || '_'); g.clientes = g.clientes || {}; return (g.clientes[k] = g.clientes[k] || {}); };
// Compara el feed del proveedor con la foto de la tienda y decide qué hay que tocar.
// Si el resultado tiene mala pinta (feed corto, demasiados cambios, demasiados agotados),
// se bloquea y avisa en vez de aplicar: un feed roto puede vaciar una tienda entera.
const cfg = $('Configuración').first().json;
const todos = $input.all().map((i) => i.json).filter(Boolean);
const feed = todos.filter((x) => x._lado === 'feed');
const tienda = todos.filter((x) => x._lado === 'tienda');
if (!feed.length) throw new Error('No llegó ninguna referencia del proveedor');
if (!tienda.length) throw new Error('No llegó ningún producto de la tienda');

// El feed trae precios de coste del proveedor: compararlos con el PVP de la tienda no dice nada.
// Lo que interesa es si el proveedor ha movido su precio desde la última sincronización.
const estado = __estadoCliente();
const preciosPrevios = estado.precios_proveedor || {};
const preciosAhora = {};

const porSku = new Map();
for (const t of tienda) if (!porSku.has(t.sku)) porSku.set(t.sku, t);

const cambios = [];
const precios = [];
const nuevos = [];
const sinGestion = [];
const enFeed = new Set();

for (const f of feed) {
  enFeed.add(f.sku);
  const t = porSku.get(f.sku);
  if (!t) {
    if (f.precio != null) preciosAhora[f.sku] = f.precio;
    nuevos.push({ sku: f.sku, titulo: f.titulo || '', stock: f.stock, precio: f.precio });
    continue;
  }
  if (f.stock !== null && f.stock !== undefined) {
    const objetivo = Math.max(0, f.stock - cfg.margen_stock);
    if (t.gestiona_stock === false) {
      if (objetivo !== t.stock) sinGestion.push({ sku: f.sku, titulo: t.titulo });
    } else if (t.stock === null || objetivo !== t.stock) {
      cambios.push({
        sku: f.sku, titulo: t.titulo, id_tienda: t.id_tienda, inventory_item_id: t.inventory_item_id,
        antes: t.stock, despues: objetivo, diferencia: t.stock === null ? null : objetivo - t.stock,
        tipo: objetivo === 0 ? 'agotado' : (t.stock === 0 || t.stock === null ? 'repuesto' : 'ajuste'),
      });
    }
  }
  if (f.precio != null) {
    preciosAhora[f.sku] = f.precio;
    const antes = preciosPrevios[f.sku];
    if (antes != null && antes > 0 && Math.abs(f.precio - antes) >= 0.01) {
      const variacion = Math.round(((f.precio - antes) / antes) * 1000) / 10;
      if (Math.abs(variacion) >= cfg.avisar_cambio_precio_pct) {
        precios.push({ sku: f.sku, titulo: t.titulo, antes, despues: f.precio, variacion_pct: variacion });
      }
    }
  }
}
const descatalogados = tienda.filter((t) => !enFeed.has(t.sku))
  .map((t) => ({ sku: t.sku, titulo: t.titulo, stock: t.stock }));

// ---- frenos de seguridad ----
const motivos = [];
const pct = (n) => Math.round((n / tienda.length) * 1000) / 10;
const es = (n) => String(n).replace('.', ',');   // 38.9 -> "38,9" en los mensajes
const agotados = cambios.filter((c) => c.tipo === 'agotado').length;
if (feed.length < cfg.min_referencias) {
  motivos.push(`el feed trae ${feed.length} referencias y el mínimo esperado es ${cfg.min_referencias}: parece incompleto`);
}
if (pct(cambios.length) > cfg.max_cambios_pct) {
  motivos.push(`cambiaría el ${es(pct(cambios.length))} % del catálogo (el tope es ${cfg.max_cambios_pct} %)`);
}
if (pct(agotados) > cfg.max_agotados_pct) {
  motivos.push(`dejaría agotado el ${es(pct(agotados))} % del catálogo (el tope es ${cfg.max_agotados_pct} %)`);
}
const bloqueado = motivos.length > 0;
// Un feed bloqueado no sirve de referencia de precios: no se guarda como foto buena.
if (!bloqueado) estado.precios_proveedor = preciosAhora;
const aplicar = !bloqueado && !cfg.modo_prueba && cambios.length > 0;

return [{ json: {
  ...cfg,
  aplicar,
  bloqueado,
  motivos,
  cambios, precios, nuevos, descatalogados, sin_gestion: sinGestion,
  resumen: {
    referencias_feed: feed.length,
    referencias_tienda: tienda.length,
    cambios: cambios.length,
    agotados,
    repuestos: cambios.filter((c) => c.tipo === 'repuesto').length,
    cambios_precio: precios.length,
    altas_nuevas: nuevos.length,
    descatalogados: descatalogados.length,
    pct_catalogo: pct(cambios.length),
  },
} }];

// Un item por cambio, con lo que necesita cada tienda para aplicarlo.
const c = $('Comparar con la tienda').first().json;
if (!c.aplicar) return [];
return c.cambios.map((x) => ({ json: {
  ...x,
  destino: c.destino,
  dominio_shopify: c.dominio_shopify,
  location_id: c.location_id,
} }));

// Cuenta qué cambios se aplicaron y cuáles fallaron (los nodos de tienda siguen aunque uno falle).
const pedidos = $('Preparar actualizaciones').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json);
const aplicados = [];
const fallidos = [];
pedidos.forEach((p, i) => {
  const r = respuestas[i] || {};
  const error = r.error || r.errorMessage || (r.errors && JSON.stringify(r.errors));
  if (error) fallidos.push({ ...p, error: String(typeof error === 'object' ? error.message || JSON.stringify(error) : error).slice(0, 200) });
  else aplicados.push(p);
});
return [{ json: { aplicado: true, aplicados, fallidos } }];

// Monta el parte de sincronización: email con la marca, aviso de Telegram y CSV con todo el detalle.
const c = $('Comparar con la tienda').first().json;
const ejecucion = $input.first().json || { aplicado: false, aplicados: [], fallidos: [] };
const r = c.resumen;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const VERDE = '#235b54'; const TINTA = '#35322c'; const SUAVE = '#6e6a61';
const REGLA = '#e7e4dc'; const PAPEL = '#f4f3ef'; const ALERTA = '#8f2f24'; const OK = '#2c5f3c';
const h3 = (t) => `<h3 style="font-family:Georgia,'Times New Roman',serif;font-size:17px;color:${VERDE};margin:24px 0 8px;font-weight:normal">${t}</h3>`;
const th = (t, der) => `<th align="${der ? 'right' : 'left'}" style="font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${REGLA};padding:6px 0;font-weight:normal">${t}</th>`;
const td = (t, der) => `<td align="${der ? 'right' : 'left'}" style="font-size:13px;color:${TINTA};border-bottom:1px solid ${REGLA};padding:8px 0">${t}</td>`;
const cifra = (n, t, color) => `<td width="25%" style="padding:0 8px"><div style="font-family:Georgia,serif;font-size:30px;color:${color || VERDE};line-height:1">${n}</div><div style="font-size:12px;color:${SUAVE};padding-top:2px">${t}</div></td>`;
const es = (n) => String(n).replace('.', ',');
const dinero = (n) => `${Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} €`;

const ETIQUETA = { agotado: 'se agota', repuesto: 'vuelve a haber', ajuste: 'ajuste' };
const filas = c.cambios.slice(0, 15).map((x) => `<tr>${td(esc(x.sku))}${td(esc(x.titulo))}` +
  td(`${x.antes ?? '—'} → <b>${x.despues}</b>`, 1) +
  td(`<span style="color:${x.tipo === 'agotado' ? ALERTA : (x.tipo === 'repuesto' ? OK : SUAVE)}">${ETIQUETA[x.tipo]}</span>`, 1) + '</tr>').join('');
const filasPrecio = c.precios.slice(0, 10).map((x) => `<tr>${td(esc(x.sku))}${td(esc(x.titulo))}` +
  td(`${dinero(x.antes)} → ${dinero(x.despues)}`, 1) +
  td(`<span style="color:${x.variacion_pct > 0 ? ALERTA : OK}">${x.variacion_pct > 0 ? '+' : '−'}${es(Math.abs(x.variacion_pct))} %</span>`, 1) + '</tr>').join('');

const aviso = (texto, color) => `<div style="border-left:3px solid ${color};background:${color === ALERTA ? '#f8eae7' : '#e9f0ea'};padding:12px 14px;border-radius:0 8px 8px 0;font-size:14px;color:${TINTA};margin:4px 0 16px">${texto}</div>`;

let cabecera = '';
if (c.bloqueado) {
  cabecera = aviso(`<b>No se ha tocado la tienda.</b> El feed del proveedor no pasa las comprobaciones de seguridad:<ul style="margin:8px 0 0;padding-left:18px">${c.motivos.map((m) => `<li>${esc(m)}</li>`).join('')}</ul>`, ALERTA);
} else if (c.modo_prueba) {
  cabecera = aviso('<b>Modo prueba.</b> Esto es lo que se aplicaría; la tienda no se ha tocado. Pon <code>modo_prueba: false</code> cuando el resultado te cuadre.', VERDE);
} else if (ejecucion.fallidos.length) {
  cabecera = aviso(`<b>${ejecucion.aplicados.length} cambios aplicados y ${ejecucion.fallidos.length} con error.</b> Los fallidos están al final del CSV adjunto.`, ALERTA);
} else if (ejecucion.aplicado) {
  cabecera = aviso(`<b>${ejecucion.aplicados.length} cambios aplicados en la tienda.</b>`, VERDE);
} else if (!c.cambios.length) {
  cabecera = aviso('La tienda ya estaba al día: el stock coincide con el del proveedor.', VERDE);
}

const cuerpo = `${cabecera}
<table width="100%" cellspacing="0" style="margin:4px 0 8px"><tr>
${cifra(r.cambios, 'cambios de stock')}${cifra(r.agotados, 'se agotan', r.agotados ? ALERTA : null)}${cifra(r.repuestos, 'vuelven a haber')}${cifra(`${es(r.pct_catalogo)} %`, 'del catálogo')}
</tr></table>
${c.cambios.length ? `${h3('Stock')}
<table width="100%" cellspacing="0" style="border-collapse:collapse"><tr>${th('Ref.')}${th('Producto')}${th('Stock', 1)}${th('', 1)}</tr>${filas}</table>
${c.cambios.length > 15 ? `<p style="font-size:12px;color:${SUAVE};margin:8px 0 0">…y ${c.cambios.length - 15} más en el CSV adjunto.</p>` : ''}` : ''}
${c.precios.length ? `${h3('El proveedor ha movido precios')}
<p style="font-size:13px;color:${SUAVE};margin:0 0 8px">Comparado con la sincronización anterior. Solo informativo: el precio de venta no se toca nunca de forma automática.</p>
<table width="100%" cellspacing="0" style="border-collapse:collapse"><tr>${th('Ref.')}${th('Producto')}${th('Coste', 1)}${th('', 1)}</tr>${filasPrecio}</table>` : ''}
${c.nuevos.length ? `${h3('Altas nuevas del proveedor')}
<p style="font-size:13px;color:${TINTA};margin:0">${c.nuevos.length} referencia(s) que el proveedor lista y la tienda no tiene: <b>${c.nuevos.slice(0, 8).map((n) => esc(n.sku)).join(', ')}</b>${c.nuevos.length > 8 ? '…' : ''}</p>` : ''}
${c.descatalogados.length ? `${h3('Ya no vienen en el feed')}
<p style="font-size:13px;color:${TINTA};margin:0">${c.descatalogados.length} referencia(s) de la tienda no aparecen en el feed. <b>No se tocan</b>: podría ser un fallo del proveedor. ${c.descatalogados.slice(0, 8).map((n) => esc(n.sku)).join(', ')}${c.descatalogados.length > 8 ? '…' : ''}</p>` : ''}
${c.sin_gestion.length ? `<p style="font-size:13px;color:${SUAVE};margin-top:16px">${c.sin_gestion.length} producto(s) tienen el stock sin gestionar en la tienda, así que se han saltado.</p>` : ''}
<p style="font-size:13px;color:${SUAVE};margin-top:20px">Feed: ${r.referencias_feed} referencias del proveedor · Tienda: ${r.referencias_tienda} productos con SKU.</p>`;

const email_html = `<!doctype html><html><body style="margin:0;background:${PAPEL};font-family:Arial,Helvetica,sans-serif;color:${TINTA}">
<table width="100%" cellspacing="0"><tr><td align="center" style="padding:24px">
<table width="680" cellspacing="0" style="background:#fff;border-radius:12px"><tr><td style="padding:28px">
<div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;color:${VERDE}">Stock · ${esc(c.tienda)}</div>
<div style="font-size:12px;color:${SUAVE};padding:2px 0 12px;border-bottom:1px solid ${REGLA}">${new Date(c.generado_en).toLocaleString('es-ES', { dateStyle: 'long', timeStyle: 'short' })} · proveedor: ${esc(c.proveedor)}</div>
${cuerpo}
<div style="border-top:1px solid ${REGLA};margin-top:24px;padding-top:12px;font-size:11px;color:${SUAVE}">Denoro Automations</div>
</td></tr></table></td></tr></table></body></html>`;

const estado = c.bloqueado ? '⛔' : (c.cambios.length ? '🔄' : '✅');
const telegram = `${estado} <b>Stock · ${c.tienda}</b>\n` +
  (c.bloqueado ? `<b>Bloqueado:</b> ${c.motivos[0]}\n` : '') +
  `<b>Cambios:</b> ${r.cambios} (${es(r.pct_catalogo)} % del catálogo)\n` +
  `<b>Se agotan:</b> ${r.agotados} · <b>Vuelven:</b> ${r.repuestos}\n` +
  (r.cambios_precio ? `<b>Precios del proveedor:</b> ${r.cambios_precio} cambios\n` : '') +
  (c.bloqueado || c.modo_prueba ? '<i>No se ha tocado la tienda.</i>'
    : `<b>Aplicados:</b> ${ejecucion.aplicados.length}${ejecucion.fallidos.length ? ` · <b>Con error:</b> ${ejecucion.fallidos.length}` : ''}`);

// ---- CSV con todo el detalle ----
const celda = (v) => {
  const s = String(v ?? '').replace(/\r?\n\s*/g, ' ').trim();
  return /[";]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const fallados = new Set(ejecucion.fallidos.map((f) => f.sku));
const lineas = [['tipo', 'sku', 'producto', 'antes', 'despues', 'estado'].join(';')];
for (const x of c.cambios) {
  lineas.push([x.tipo, x.sku, x.titulo, x.antes, x.despues,
    c.bloqueado ? 'bloqueado' : (c.modo_prueba ? 'solo prueba' : (fallados.has(x.sku) ? 'ERROR' : 'aplicado'))].map(celda).join(';'));
}
for (const x of c.precios) lineas.push(['precio', x.sku, x.titulo, x.antes, x.despues, 'informativo'].map(celda).join(';'));
for (const x of c.nuevos) lineas.push(['alta nueva', x.sku, x.titulo, '', x.stock, 'informativo'].map(celda).join(';'));
for (const x of c.descatalogados) lineas.push(['sin feed', x.sku, x.titulo, x.stock, '', 'informativo'].map(celda).join(';'));
for (const x of ejecucion.fallidos) lineas.push(['error', x.sku, x.titulo, x.antes, x.despues, x.error].map(celda).join(';'));

// Sin cambios de stock ni de precio, sin bloqueo y sin fallos no hay nada que contar: no se manda nada.
const hayAlgo = Boolean(c.bloqueado || r.cambios || r.cambios_precio || (ejecucion.fallidos || []).length);
return [{
  json: {
    ...c,
    enviar_email: Boolean(c.enviar_email && hayAlgo),
    enviar_telegram: Boolean(c.enviar_telegram && hayAlgo),
    hay_algo: hayAlgo,
    asunto: c.bloqueado
      ? `⛔ Denoro · Stock de ${c.tienda}: feed bloqueado`
      : `Denoro · Stock de ${c.tienda}: ${r.cambios} cambios${c.modo_prueba ? ' (prueba)' : ''}`,
    email_html, telegram,
    ejecucion,
  },
  binary: lineas.length > 1 ? { cambios: {
    data: Buffer.from('﻿' + lineas.join('\n'), 'utf8').toString('base64'),
    mimeType: 'text/csv', fileName: `stock-${new Date(c.generado_en).toISOString().slice(0, 10)}.csv`, fileExtension: 'csv',
  } } : {},
}];

// (Se añade a cada automatización en su versión «para un cliente»)
// Guarda en denoro_estado lo que ha pasado en esta ejecución, para enseñarlo en el panel.
const d = $input.first()?.json || {};
const cfg = $('Configuración').first().json;
const txt = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const titulo = txt(d.asunto).replace(/^[^\p{L}\p{N}]*Denoro · /u, '').replace(/^[^\p{L}\p{N}]+/u, '');
return [{ json: {
  clave: cfg.__clave, token: cfg.__token, snapshot: '',
  resumen: JSON.stringify({
    ultima: new Date().toISOString(), ok: true, modo: cfg.modo || null,
    titulo: (titulo || "Sin cambios de stock").slice(0, 200),
    texto: txt(d.telegram).slice(0, 1500),
    avisado: Boolean(d.asunto && (d.enviar_email || d.enviar_telegram)),
    demo: [cfg.fuente, cfg.destino].includes('demo'),
  }),
} }];
